function enableResultControls(enabled){["exportExcelButton","exportPngButton","playButton","resetAnimButton","speedInput"].forEach(id=>$(id).disabled=!enabled);}

// Attach Import Excel immediately; it does not depend on GLPK.
$("importButton").addEventListener("click",()=>{fileInput.value="";fileInput.click();});
fileInput.addEventListener("change",async event=>{const file=event.target.files[0];if(!file)return;try{if(typeof XLSX==="undefined")throw new Error("SheetJS did not load. Check the Internet connection.");setStatus(`Reading ${file.name}…`);const buffer=await file.arrayBuffer();const wb=XLSX.read(buffer,{type:"array",cellDates:true});const sheets=workbookToSheets(wb);loadData(sheets,file.name);}catch(error){setStatus(`Import error: ${error.message}`,"error");}});
$("demoButton").addEventListener("click",()=>loadData(deepClone(BUILTIN_DEMO),"Built-in ultra-complex demo"));
$("downloadExampleButton").addEventListener("click",()=>{const bytes=Uint8Array.from(atob(EXAMPLE_XLSX_B64),c=>c.charCodeAt(0));downloadBlob(new Blob([bytes],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}),"stage1_example_input_v8_6_4_6_ultra_complex.xlsx");});

async function initSolver(){const urls=["https://cdn.jsdelivr.net/npm/glpk.js@5.0.0/+esm","https://cdn.jsdelivr.net/npm/glpk.js@4.0.2/+esm","https://esm.sh/glpk.js@4.0.2"];
  for(const url of urls){try{const mod=await import(url);const factory=mod.default||mod.GLPK||mod;state.glpk=await factory();state.solverReady=true;setStatus(`Import Excel is ready. GLPK ${state.glpk.version||"browser solver"} loaded.`,"success");updateSolveButtons();return;}catch(error){console.warn("GLPK load failed",url,error);}}
  setStatus("Import Excel works, but GLPK could not load. Check Internet access or CDN blocking.","warning");
}
initBackend();

function workbookToSheets(wb){const out={};for(const desired of ["Supply","Demand","Params","Arcs","Nodes","NodeConstraints","AllowedConnections"]){const name=wb.SheetNames.find(x=>x.trim().toLowerCase()===desired.toLowerCase());if(name)out[desired]=XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:null,raw:true});}return out;}

function loadData(rawSheets,name){try{state.validation=[];logValidation(`Source: ${name}`);const data=readAndNormalize(rawSheets);validateData(data,$("enforceEchelon").checked);state.data=data;state.sourceName=name;state.lp=null;state.milp=null;state.current=null;enableDataControls(true);enableResultControls(false);clearOutputs();drawNetwork(null);drawGIS(null);substatusEl.textContent=`${name} | Supply rows ${data.Supply.length} | Demand rows ${data.Demand.length} | Active arcs ${data.Arcs.length} | Enabled nodes ${data.Nodes.length}`;setStatus("Workbook loaded and validated. Ready for LP/MILP.","success");}catch(error){state.data=null;enableDataControls(false);setStatus(`Validation error: ${error.message}`,"error");logValidation(`ERROR: ${error.message}`);}}

function readAndNormalize(sheets){for(const req of ["Supply","Demand","Params","Arcs"]){if(!Array.isArray(sheets[req]))throw new Error(`Required sheet ${req} was not found.`);}
  const Supply=sheets.Supply.map(r=>({IP:str(r.IP),Supply:num(r.Supply)}));
  const Demand=sheets.Demand.map(r=>({DC:str(r.DC),Demand:num(r.Demand)}));
  const Params=sheets.Params.map(r=>({Key:str(r.Key),Value:optNum(r.Value)})).filter(r=>r.Key);
  const ParamMap={};for(const r of Params)ParamMap[validName(r.Key)]=r.Value;
  const arcsRaw=sheets.Arcs.map(r=>({From:str(r.From),To:str(r.To),Mode:str(r.Mode),UnitCost:num(r.UnitCost),FixedCost:isBlank(r.FixedCost)?0:num(r.FixedCost),Cap:isBlank(r.Cap)?Infinity:optNum(r.Cap),Enabled:isBlank(r.Enabled)?1:num(r.Enabled),IsExport:isBlank(r.IsExport)?0:num(r.IsExport),Notes:str(r.Notes)}));
  let Nodes;
  if(Array.isArray(sheets.Nodes)&&sheets.Nodes.length){Nodes=sheets.Nodes.map(r=>({Node:str(r.Node),Role:str(r.Role),NodeLevel:num(r.NodeLevel),Enabled:isBlank(r.Enabled)?1:num(r.Enabled),CandidateOpen:isBlank(r.CandidateOpen)?(str(r.Role)==="Intermediate"?1:0):num(r.CandidateOpen),MustOpen:isBlank(r.MustOpen)?(str(r.Role)==="Intermediate"?0:1):num(r.MustOpen),FixedOpenCost:isBlank(r.FixedOpenCost)?0:num(r.FixedOpenCost),CapWhenOpen:isBlank(r.CapWhenOpen)?Infinity:optNum(r.CapWhenOpen),Description:str(r.Description),Lat:optNum(r.Lat),Lon:optNum(r.Lon)}));}
  else{const names=unique([...Supply.map(r=>r.IP),...Demand.map(r=>r.DC),...arcsRaw.flatMap(r=>[r.From,r.To])]);const exportNodes=unique(arcsRaw.filter(r=>r.IsExport===1).map(r=>r.To));Nodes=names.map(Node=>{let Role="Intermediate";if(Supply.some(r=>r.IP===Node))Role="Supply";else if(Demand.some(r=>r.DC===Node))Role="Demand";else if(exportNodes.includes(Node))Role="ExportSink";return{Node,Role,NodeLevel:Role==="Supply"?1:Role==="Intermediate"?2:Role==="Demand"?3:4,Enabled:1,CandidateOpen:Role==="Intermediate"?1:0,MustOpen:Role==="Intermediate"?0:1,FixedOpenCost:0,CapWhenOpen:Infinity,Description:"",Lat:NaN,Lon:NaN};});logValidation("Optional Nodes sheet missing; default nodes were derived.");}
  Nodes=Nodes.filter(r=>r.Enabled===1);
  const nodeMap=new Map(Nodes.map((r,i)=>[r.Node,i]));
  const Arcs=arcsRaw.filter(r=>r.Enabled===1).map(r=>{if(!nodeMap.has(r.From)||!nodeMap.has(r.To))throw new Error(`Arc ${r.From}->${r.To} references a disabled or unknown node.`);return{...r,FromLevel:Nodes[nodeMap.get(r.From)].NodeLevel,ToLevel:Nodes[nodeMap.get(r.To)].NodeLevel};});
  const paramNC=Nodes.map(n=>({Node:n.Node,FixFlow:getParam(ParamMap,`${validName(n.Node)}_FixFlow`,NaN),MinFlow:getParam(ParamMap,`${validName(n.Node)}_MinFlow`,NaN),MaxFlow:getParam(ParamMap,`${validName(n.Node)}_MaxFlow`,NaN),FlowType:getParam(ParamMap,`${validName(n.Node)}_FlowType`,0)}));
  const sheetNC=Array.isArray(sheets.NodeConstraints)?sheets.NodeConstraints.map(r=>({Node:str(r.Node),FixFlow:optNum(r.FixFlow),MinFlow:optNum(r.MinFlow),MaxFlow:optNum(r.MaxFlow),FlowType:isBlank(r.FlowType)?NaN:optNum(r.FlowType)})):[];
  const NodeConstraints=Nodes.map(n=>{const p=paramNC.find(x=>x.Node===n.Node)||{FixFlow:NaN,MinFlow:NaN,MaxFlow:NaN,FlowType:0};const s=sheetNC.find(x=>x.Node===n.Node);return{Node:n.Node,FixFlow:s&&!Number.isNaN(s.FixFlow)?s.FixFlow:p.FixFlow,MinFlow:s&&!Number.isNaN(s.MinFlow)?s.MinFlow:p.MinFlow,MaxFlow:s&&!Number.isNaN(s.MaxFlow)?s.MaxFlow:p.MaxFlow,FlowType:s&&!Number.isNaN(s.FlowType)?s.FlowType:p.FlowType};});
  let AllowedConnections;
  if(Array.isArray(sheets.AllowedConnections)&&sheets.AllowedConnections.length){AllowedConnections=sheets.AllowedConnections.map(r=>({FromLevel:num(r.FromLevel),ToLevel:num(r.ToLevel),Enabled:isBlank(r.Enabled)?1:num(r.Enabled),Notes:str(r.Notes)}));}
  else{const levels=unique(Nodes.map(r=>r.NodeLevel)).sort((a,b)=>a-b);AllowedConnections=[];for(const from of levels)for(const to of levels)AllowedConnections.push({FromLevel:from,ToLevel:to,Enabled:(to===from+1||(from===2&&to===4)||(from===1&&to===3))?1:0,Notes:"Auto-generated"});logValidation("Optional AllowedConnections missing; defaults were generated.");}
  return{Supply,Demand,Params,ParamMap,Arcs,ArcsAll:arcsRaw,Nodes,NodeConstraints,AllowedConnections};
}

function validateData(d,enforce){if(d.Supply.some(r=>!r.IP||r.Supply<0))throw new Error("Supply values and IP names are invalid.");if(d.Demand.some(r=>!r.DC||r.Demand<0))throw new Error("Demand values and DC names are invalid.");if(d.Arcs.some(r=>r.UnitCost<0||r.FixedCost<0||!(r.Cap>0||r.Cap===Infinity)))throw new Error("Arc cost/capacity values are invalid.");
  const nodeNames=d.Nodes.map(r=>r.Node);if(unique(nodeNames).length!==nodeNames.length)throw new Error("Duplicate nodes found in Nodes.");const roles=new Set(["Supply","Intermediate","Demand","ExportSink"]);for(const n of d.Nodes){if(!roles.has(n.Role))throw new Error(`Node ${n.Node} has invalid Role ${n.Role}.`);if(!Number.isInteger(n.NodeLevel)||n.NodeLevel<1)throw new Error(`Node ${n.Node} has invalid NodeLevel.`);if(![0,1].includes(n.CandidateOpen)||![0,1].includes(n.MustOpen))throw new Error(`Node ${n.Node} has invalid open flags.`);if(n.FixedOpenCost<0||!(n.CapWhenOpen>0||n.CapWhenOpen===Infinity))throw new Error(`Node ${n.Node} has invalid opening data.`);if(["Supply","Demand","ExportSink"].includes(n.Role))n.MustOpen=1;}
  const nodeMap=new Map(d.Nodes.map(r=>[r.Node,r]));for(const s of d.Supply){if(!nodeMap.has(s.IP)||nodeMap.get(s.IP).Role!=="Supply")throw new Error(`Supply node ${s.IP} is missing or has the wrong role.`);}for(const q of d.Demand){if(!nodeMap.has(q.DC)||nodeMap.get(q.DC).Role!=="Demand")throw new Error(`Demand node ${q.DC} is missing or has the wrong role.`);}
  for(const c of d.NodeConstraints){if(!nodeMap.has(c.Node))throw new Error(`NodeConstraints references unknown node ${c.Node}.`);if(![0,1,2,3].includes(Number(c.FlowType)))throw new Error(`FlowType for ${c.Node} must be 0,1,2,3.`);}
  const keys=new Set();for(const a of d.Arcs){if(a.From===a.To)throw new Error(`Self-loop not allowed: ${a.From}->${a.To}.`);const key=`${a.From}->${a.To}|${a.Mode}`;if(keys.has(key))throw new Error(`Duplicate arc ${key}.`);keys.add(key);if(enforce&&!isAllowed(d.AllowedConnections,a.FromLevel,a.ToLevel))throw new Error(`Invalid echelon arc ${a.From}->${a.To} (L${a.FromLevel}->L${a.ToLevel}).`);}
  logValidation(`Validation OK: ${d.Nodes.length} nodes, ${d.Arcs.length} enabled arcs.`);logValidation(`Total supply = ${fmt(sum(d.Supply.map(r=>r.Supply)))}; domestic demand = ${fmt(sum(d.Demand.map(r=>r.Demand)))}; minimum export = ${fmt(getParam(d.ParamMap,"exportDemand",0))}.`);
}
function isAllowed(rows,from,to){return rows.some(r=>r.FromLevel===from&&r.ToLevel===to&&r.Enabled===1);}

$("validateButton").addEventListener("click",()=>{try{state.validation=[];validateData(state.data,$("enforceEchelon").checked);setStatus("Validation completed successfully.","success");}catch(error){setStatus(error.message,"error");logValidation(`ERROR: ${error.message}`);}});
$("runLPButton").addEventListener("click",()=>solveAndShow(false));$("runMILPButton").addEventListener("click",()=>solveAndShow(true));$("runBothButton").addEventListener("click",async()=>{try{await solveAndShow(false,false);await solveAndShow(true,false);refreshAll();openTab("kpiTab");setStatus("LP and MILP completed.","success");}catch(error){setStatus(error.message,"error");}});

async function solveAndShow(useMILP,refresh=true){if(!state.data)throw new Error("Import or load a workbook first.");validateData(state.data,$("enforceEchelon").checked);setStatus(`Solving ${useMILP?"MILP":"LP"}…`);await sleep(20);const result=await backendSolveModel(state.data,useMILP);result.source=state.sourceName;result.label=useMILP?"MILP":"LP";if(useMILP)state.milp=result;else state.lp=result;state.current=result;enableResultControls(true);buildAnimationParticles(result);if(refresh)refreshAll();setStatus(`${result.label} solved. TotalCost=${fmt(result.totalCost)}; UsedArcs=${result.KPI.UsedArcs}; OpenNodes=${result.KPI.OpenNodes}.`,"success");return result;}

async function backendSolveModel(data, useMILP, solveOptions = {}) {
  const body = JSON.stringify({ data, useMILP, solveOptions });
  const response = await window.oseSolveFetch("/api/solve", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Accept": "application/json" },
    body
  });
  let payload;
  try { payload = await response.json(); } catch (_) { payload = null; }
  if (!response.ok) {
    const detail = payload && payload.detail ? payload.detail : `Backend request failed (${response.status}).`;
    throw new Error(typeof detail === "string" ? detail : JSON.stringify(detail));
  }
  if (!payload || payload.ok !== true || !payload.result) {
    throw new Error("Backend returned an invalid solver response.");
  }
  return payload.result;
}

async function apiGet(path) {
  const res = await window.oseFetch(path, { cache: "no-store" });
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); } catch { throw new Error(`Máy chủ trả về phản hồi không hợp lệ (HTTP ${res.status})`); }
  if (!res.ok) throw new Error(typeof data.detail === "string" ? data.detail : "Backend error");
  return data;
}

async function initBackend() {
  const sel = $("backendSelect");
  const local = ["localhost", "127.0.0.1"].includes(location.hostname);
  if (local) sel.hidden = true;
  let pinned = new URLSearchParams(location.search).get("api");
  try { pinned = pinned || localStorage.getItem("ose_api"); } catch (e) {}
  sel.value = ["home", "render"].includes(pinned) ? pinned : "auto";
  sel.onchange = () => { const u = new URL(location.href); u.searchParams.set("api", sel.value); location.href = u.toString(); };
  const base = String(await window.OSE_API_READY || "");
  const name = base.includes("onrender.com") ? "Render" : (local ? "Cục bộ" : "Home server");
  const t0 = performance.now();
  try {
    const h = await apiGet("/api/health");
    $("backendDot").className = "dot ok";
    $("backendText").textContent = `${name} · v${h.version || "?"} · ${Math.round(performance.now() - t0)} ms`;
    state.solverReady = true;
    updateSolveButtons();
  } catch (e) {
    $("backendDot").className = "dot bad";
    $("backendText").textContent = `${name} · mất kết nối`;
    setStatus("Không kết nối được máy chủ tính toán. Thử chọn Render hoặc tải lại trang.", "warning");
  }
}

async function solveModel(data,useMILP,solveOptions={}){const g=state.glpk,T=data.Arcs,nA=T.length,nN=data.Nodes.length,p=data.ParamMap;const x=T.map((_,i)=>`x_${i}`),y=T.map((_,i)=>`y_${i}`),z=data.Nodes.map((_,i)=>`z_${i}`);const nodeIndex=new Map(data.Nodes.map((n,i)=>[n.Node,i]));
  const modeCap={Road:getParam(p,"K_road",Infinity),Rail:getParam(p,"K_rail",Infinity),Water:getParam(p,"K_water",Infinity),Sea:getParam(p,"K_sea",Infinity)};const modeCO2={Road:getParam(p,"EF_road",0),Rail:getParam(p,"EF_rail",0),Water:getParam(p,"EF_water",0),Sea:getParam(p,"EF_sea",0)};
  const ef=T.map(a=>modeCO2[a.Mode]||0),handling=T.map(a=>nodeHandling(p,a.To)),lambda=getParam(p,"lambdaCO2",0),BigM=getParam(p,"BigM",1e6),exportDemand=getParam(p,"exportDemand",0),Emax=getParam(p,"Emax",Infinity);const varCost=T.map((a,i)=>a.UnitCost+handling[i]+lambda*ef[i]);
  const objective=[];T.forEach((a,i)=>{objective.push({name:x[i],coef:varCost[i]});if(useMILP)objective.push({name:y[i],coef:a.FixedCost});});if(useMILP)data.Nodes.forEach((n,i)=>objective.push({name:z[i],coef:n.FixedOpenCost}));
  const subjectTo=[],bounds=[];const binaries=[];const rowVars=obj=>Object.entries(obj).filter(([,c])=>Math.abs(c)>1e-12).map(([name,coef])=>({name,coef}));
  const eq=(name,obj,val)=>subjectTo.push({name,vars:rowVars(obj),bnds:{type:g.GLP_FX,lb:val,ub:val}});const up=(name,obj,val)=>subjectTo.push({name,vars:rowVars(obj),bnds:{type:g.GLP_UP,lb:0,ub:val}});const lo=(name,obj,val)=>subjectTo.push({name,vars:rowVars(obj),bnds:{type:g.GLP_LO,lb:val,ub:0}});
  const net=node=>{const r={};T.forEach((a,i)=>{if(a.From===node)r[x[i]]=(r[x[i]]||0)+1;if(a.To===node)r[x[i]]=(r[x[i]]||0)-1;});return r;};
  data.Supply.forEach((s,i)=>eq(`supply_${i}`,net(s.IP),s.Supply));data.Demand.forEach((d,i)=>{const r=net(d.DC);for(const k of Object.keys(r))r[k]*=-1;eq(`demand_${i}`,r,d.Demand);});data.Nodes.forEach((n,i)=>{if(n.Role==="Intermediate"){const r={};T.forEach((a,k)=>{if(a.To===n.Node)r[x[k]]=(r[x[k]]||0)+1;if(a.From===n.Node)r[x[k]]=(r[x[k]]||0)-1;});eq(`conservation_${i}`,r,0);}});
  if(exportDemand>0){const sinks=new Set(data.Nodes.filter(n=>n.Role==="ExportSink").map(n=>n.Node));const r={};T.forEach((a,i)=>{if(sinks.has(a.To)&&a.IsExport===1)r[x[i]]=1;});if(!Object.keys(r).length)throw new Error("exportDemand > 0 but no enabled export arc reaches an ExportSink.");lo("export_min",r,exportDemand);}
  for(const [mode,cap] of Object.entries(modeCap)){if(Number.isFinite(cap)){const r={};T.forEach((a,i)=>{if(a.Mode===mode)r[x[i]]=1;});up(`mode_${mode}`,r,cap);}}
  data.Nodes.forEach((n,i)=>{const K=nodeCapacity(p,n.Node);if(Number.isFinite(K)){const r={};T.forEach((a,k)=>{if(a.To===n.Node)r[x[k]]=1;});up(`nodecap_${i}`,r,K);}if(useMILP){if(Number.isFinite(n.CapWhenOpen)){const r={[z[i]]:-n.CapWhenOpen};T.forEach((a,k)=>{if(a.To===n.Node)r[x[k]]=(r[x[k]]||0)+1;});up(`capopen_${i}`,r,0);}const M=localNodeM(T,n.Node,BigM);const rin={[z[i]]:-M},rout={[z[i]]:-M};T.forEach((a,k)=>{if(a.To===n.Node)rin[x[k]]=(rin[x[k]]||0)+1;if(a.From===n.Node)rout[x[k]]=(rout[x[k]]||0)+1;});up(`closed_in_${i}`,rin,0);up(`closed_out_${i}`,rout,0);}});
  data.NodeConstraints.forEach((c,i)=>{if(Number(c.FlowType)===0)return;const r={};T.forEach((a,k)=>{if((c.FlowType===1||c.FlowType===3)&&a.To===c.Node)r[x[k]]=(r[x[k]]||0)+1;if((c.FlowType===2||c.FlowType===3)&&a.From===c.Node)r[x[k]]=(r[x[k]]||0)+1;});if(Number.isFinite(c.FixFlow))eq(`flowfix_${i}`,r,c.FixFlow);else{if(Number.isFinite(c.MinFlow))lo(`flowmin_${i}`,r,c.MinFlow);if(Number.isFinite(c.MaxFlow))up(`flowmax_${i}`,r,c.MaxFlow);}});
  if(Number.isFinite(Emax)){const r={};T.forEach((a,i)=>r[x[i]]=ef[i]);up("emission_cap",r,Emax);}
  T.forEach((a,i)=>{bounds.push({name:x[i],type:Number.isFinite(a.Cap)?g.GLP_DB:g.GLP_LO,lb:0,ub:Number.isFinite(a.Cap)?a.Cap:0});if(useMILP){bounds.push({name:y[i],type:g.GLP_DB,lb:0,ub:1});binaries.push(y[i]);const M=Math.min(BigM,a.Cap);up(`activation_${i}`,{[x[i]]:1,[y[i]]:-M},0);up(`linkfrom_${i}`,{[y[i]]:1,[z[nodeIndex.get(a.From)]]:-1},0);up(`linkto_${i}`,{[y[i]]:1,[z[nodeIndex.get(a.To)]]:-1},0);}});
  if(useMILP)data.Nodes.forEach((n,i)=>{const fixed=(n.CandidateOpen===0||n.MustOpen===1);bounds.push({name:z[i],type:fixed?g.GLP_FX:g.GLP_DB,lb:fixed?1:0,ub:1});binaries.push(z[i]);});
  const model={name:useMILP?"MultiLayer_MILP":"MultiLayer_LP",objective:{direction:g.GLP_MIN,name:"TotalCost",vars:objective},subjectTo,bounds};if(useMILP)model.binaries=binaries;
  const solution=await g.solve(model,{msglev:g.GLP_MSG_ERR,presol:true,tmlim:Number.isFinite(solveOptions.tmlim)?solveOptions.tmlim:120,mipgap:Number.isFinite(solveOptions.mipgap)?solveOptions.mipgap:0.001});const status=solution.result.status;if(![g.GLP_OPT,g.GLP_FEAS].includes(status))throw new Error(`GLPK returned status ${status}; model may be infeasible or unbounded.`);const vars=solution.result.vars;const xv=x.map(n=>vars[n]||0),yv=useMILP?y.map(n=>vars[n]||0):xv.map(v=>v>1e-8?1:0),zv=useMILP?z.map(n=>vars[n]||0):data.Nodes.map(()=>1);
  return postprocess({x:xv,y:yv,zNode:zv,totalCost:solution.result.z,status,time:solution.time,useMILP},data,{ef,varCost});
}

function postprocess(raw,data,model){const T=data.Arcs,tol=1e-8;const arcCost=T.map((a,i)=>raw.x[i]*model.varCost[i]+(raw.useMILP?(raw.y[i]>0.5?1:0):0)*a.FixedCost),util=T.map((a,i)=>100*raw.x[i]/Math.max(a.Cap,Number.EPSILON)),co2=T.map((a,i)=>raw.x[i]*model.ef[i]);
  const all=T.map((a,i)=>({From:a.From,To:a.To,Mode:a.Mode,Flow:raw.x[i],OpenY:raw.y[i],IsUsed:raw.x[i]>tol,UnitCost:a.UnitCost,FixedCost:a.FixedCost,ArcCost:arcCost[i],IsExport:a.IsExport,Cap:a.Cap,CO2:co2[i],UtilPct:util[i],FromLevel:a.FromLevel,ToLevel:a.ToLevel}));const used=all.filter(r=>r.IsUsed);
  const nodeSummary=data.Nodes.map((n,i)=>{const inflow=sum(T.map((a,k)=>a.To===n.Node?raw.x[k]:0)),outflow=sum(T.map((a,k)=>a.From===n.Node?raw.x[k]:0));const c=data.NodeConstraints.find(x=>x.Node===n.Node)||{};return{...n,Inflow:inflow,Outflow:outflow,Throughput:inflow+outflow,Net:inflow-outflow,NodeOpen:raw.zNode[i],OpenFixedCostPaid:raw.useMILP*raw.zNode[i]*n.FixedOpenCost,FixFlow:c.FixFlow,MinFlow:c.MinFlow,MaxFlow:c.MaxFlow,FlowType:c.FlowType};}).sort((a,b)=>a.NodeLevel-b.NodeLevel||a.Node.localeCompare(b.Node));
  const nodeOpen=data.Nodes.map((n,i)=>({Node:n.Node,Role:n.Role,NodeLevel:n.NodeLevel,CandidateOpen:n.CandidateOpen,MustOpen:n.MustOpen,FixedOpenCost:n.FixedOpenCost,CapWhenOpen:n.CapWhenOpen,NodeOpen:raw.zNode[i],OpenCostPaid:raw.useMILP*raw.zNode[i]*n.FixedOpenCost}));
  const levels=unique(data.Nodes.map(n=>n.NodeLevel)).sort((a,b)=>a-b),flowBy=[];for(const f of levels)for(const t of levels)flowBy.push({FromLevel:f,ToLevel:t,Flow:sum(all.filter(a=>a.FromLevel===f&&a.ToLevel===t).map(a=>a.Flow))});
  const modeSummary=["Road","Rail","Water","Sea"].map(m=>({Mode:m,Flow:sum(all.filter(a=>a.Mode===m).map(a=>a.Flow)),CO2:sum(all.filter(a=>a.Mode===m).map(a=>a.CO2)),ArcCost:sum(all.filter(a=>a.Mode===m).map(a=>a.ArcCost))}));
  const KPI={TotalSupply:sum(data.Supply.map(r=>r.Supply)),TotalDemand:sum(data.Demand.map(r=>r.Demand)),TotalExport:sum(T.map((a,i)=>a.IsExport===1?raw.x[i]:0)),TotalCO2:sum(co2),OpenArcs:sum(raw.y.map(v=>v>0.5?1:0)),UsedArcs:used.length,OpenNodes:sum(raw.zNode.map(v=>v>0.5?1:0)),FixedNodeCostPaid:sum(nodeOpen.map(r=>r.OpenCostPaid))};
  return{...raw,AllArcTable:all,UsedArcTable:used,NodeSummary:nodeSummary,NodeOpenTable:nodeOpen,FlowByEchelon:flowBy,ModeSummary:modeSummary,KPI,T:data.Arcs,Nodes:data.Nodes};
}

