function filteredArcs(r,includeUnused=false){const mode=$("modeSelect").value;return r.AllArcTable.filter(a=>(mode==="All"||a.Mode===mode)&&(a.IsUsed||includeUnused));}
function levelPositions(nodes,width,height){const levels=unique(nodes.map(n=>n.NodeLevel)).sort((a,b)=>a-b),pos=new Map();levels.forEach((level,li)=>{const group=nodes.filter(n=>n.NodeLevel===level);group.forEach((n,i)=>pos.set(n.Node,{x:70+li*(width-140)/Math.max(levels.length-1,1),y:65+(i+1)*(height-120)/(group.length+1)}));});return pos;}
function drawNetwork(r){const c=$("networkCanvas"),ctx=c.getContext("2d"),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle="#fff";ctx.fillRect(0,0,w,h);if(!state.data){centerText(ctx,w,h,"Load a workbook to display the network.");return;}const pos=levelPositions(state.data.Nodes,w,h);if(r&&$("showClosed").checked){for(const a of filteredArcs(r,true).filter(a=>!a.IsUsed))drawEdge(ctx,pos,a,"#c8ced7",1,true,null);}if(r){for(const a of filteredArcs(r,false))drawEdge(ctx,pos,a,modeColors[a.Mode]||"#111",Math.min(6,1.5+Math.sqrt(a.Flow)/3),false,a.Flow);}for(const n of state.data.Nodes)drawNode(ctx,n,pos.get(n.Node));}
function drawEdge(ctx,pos,a,color,width,dashed,label){const p=pos.get(a.From),q=pos.get(a.To);if(!p||!q)return;const dx=q.x-p.x,dy=q.y-p.y,L=Math.hypot(dx,dy)||1,ux=dx/L,uy=dy/L,s={x:p.x+ux*18,y:p.y+uy*18},e={x:q.x-ux*20,y:q.y-uy*20};ctx.save();ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=width;ctx.setLineDash(dashed?[7,5]:[]);ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(e.x,e.y);ctx.stroke();const ang=Math.atan2(e.y-s.y,e.x-s.x),head=7;ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.lineTo(e.x-head*Math.cos(ang-Math.PI/6),e.y-head*Math.sin(ang-Math.PI/6));ctx.lineTo(e.x-head*Math.cos(ang+Math.PI/6),e.y-head*Math.sin(ang+Math.PI/6));ctx.closePath();ctx.fill();if(label!=null){ctx.font="10px Arial";ctx.textAlign="center";const mx=(s.x+e.x)/2,my=(s.y+e.y)/2,text=fmt(label),m=ctx.measureText(text);ctx.fillStyle="rgba(255,255,255,.9)";ctx.fillRect(mx-m.width/2-3,my-9,m.width+6,14);ctx.fillStyle="#111";ctx.fillText(text,mx,my+2);}ctx.restore();}
function drawNode(ctx,n,p){if(!p)return;ctx.save();ctx.fillStyle=n.Role==="Supply"?"#e5e7eb":n.Role==="Demand"?"#dbeafe":n.Role==="ExportSink"?"#fef3c7":n.NodeOpen===0?"#f1f5f9":"#dcfce7";ctx.strokeStyle="#334155";ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(p.x,p.y,15,0,Math.PI*2);ctx.fill();ctx.stroke();if($("showLabels").checked){ctx.fillStyle="#111";ctx.font="10px Arial";ctx.textAlign="left";ctx.fillText(n.Node,p.x+18,p.y+4);}ctx.restore();}

function drawGIS(r){const c=$("gisCanvas"),ctx=c.getContext("2d"),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle="#f8fafc";ctx.fillRect(0,0,w,h);if(!state.data){centerText(ctx,w,h,"Load a workbook to display GIS coordinates.");return;}const geo=state.data.Nodes.filter(n=>Number.isFinite(n.Lat)&&Number.isFinite(n.Lon));if(!geo.length){centerText(ctx,w,h,"No Lat/Lon data are available in Nodes.");return;}const minLat=Math.min(...geo.map(n=>n.Lat)),maxLat=Math.max(...geo.map(n=>n.Lat)),minLon=Math.min(...geo.map(n=>n.Lon)),maxLon=Math.max(...geo.map(n=>n.Lon));const pos=new Map(geo.map(n=>[n.Node,{x:55+(n.Lon-minLon)/(Math.max(maxLon-minLon,1e-9))*(w-110),y:h-55-(n.Lat-minLat)/(Math.max(maxLat-minLat,1e-9))*(h-110)}]));ctx.strokeStyle="#e2e8f0";ctx.lineWidth=1;for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(i*w/8,25);ctx.lineTo(i*w/8,h-25);ctx.stroke();ctx.beginPath();ctx.moveTo(25,i*h/8);ctx.lineTo(w-25,i*h/8);ctx.stroke();}if(r&&$("showClosed").checked){for(const a of filteredArcs(r,true).filter(a=>!a.IsUsed))drawEdge(ctx,pos,a,"#c8ced7",1,true,null);}if(r)for(const a of filteredArcs(r,false))drawEdge(ctx,pos,a,modeColors[a.Mode]||"#111",2.5,false,a.Flow);for(const n of geo)drawNode(ctx,n,pos.get(n.Node));ctx.fillStyle="#475569";ctx.font="11px Arial";ctx.textAlign="left";ctx.fillText(`Lon ${minLon.toFixed(3)}–${maxLon.toFixed(3)}`,20,h-12);ctx.fillText(`Lat ${minLat.toFixed(3)}–${maxLat.toFixed(3)}`,20,18);}

