function chart(canvasId,type,labels,datasets,yLabel){if(charts[canvasId])charts[canvasId].destroy();charts[canvasId]=new Chart($(canvasId),{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,animation:false,scales:{y:{beginAtZero:true,title:{display:true,text:yLabel}},x:{ticks:{maxRotation:60,minRotation:0}}}}});}
function updateComparison(){if(!state.lp&&!state.milp)return;const results=[state.lp,state.milp].filter(Boolean),labels=results.map(r=>r.label);chart("networkKpiChart","bar",["UsedArcs","OpenArcs","OpenNodes"],results.map(r=>({label:r.label,data:[r.KPI.UsedArcs,r.KPI.OpenArcs,r.KPI.OpenNodes]})),"Count");chart("flowKpiChart","bar",["Supply","Demand","Export","CO2"],results.map(r=>({label:r.label,data:[r.KPI.TotalSupply,r.KPI.TotalDemand,r.KPI.TotalExport,r.KPI.TotalCO2]})),"Value");chart("costKpiChart","bar",["TotalCost","NodeFixedCost"],results.map(r=>({label:r.label,data:[r.totalCost,r.KPI.FixedNodeCostPaid]})),"Cost");}

function buildAnimationParticles(r){const pos=levelPositions(r.Nodes,$("animationCanvas").width,$("animationCanvas").height),arcs=filteredArcs(r,false);state.animation.particles=arcs.flatMap(a=>{const p=pos.get(a.From),q=pos.get(a.To),count=Math.max(1,Math.min(6,Math.ceil(Math.sqrt(a.Flow)/2)));return Array.from({length:count},(_,i)=>({p,q,color:modeColors[a.Mode],offset:i/count,speed:.08+.02*(i%3)}));});state.animation.t=0;drawAnimation();}
$("playButton").addEventListener("click",()=>{state.animation.playing=!state.animation.playing;$("playButton").textContent=state.animation.playing?"Pause":"Play";state.animation.last=null;if(state.animation.playing)state.animation.requestId=requestAnimationFrame(animationLoop);});$("resetAnimButton").addEventListener("click",()=>{stopAnimation();state.animation.t=0;drawAnimation();});$("speedInput").addEventListener("input",()=>$("speedLabel").textContent=`${Number($("speedInput").value).toFixed(2)}×`);
function animationLoop(ts){if(!state.animation.playing)return;if(state.animation.last==null)state.animation.last=ts;const dt=(ts-state.animation.last)/1000;state.animation.last=ts;state.animation.t+=dt*Number($("speedInput").value);drawAnimation();state.animation.requestId=requestAnimationFrame(animationLoop);}
function stopAnimation(){state.animation.playing=false;$("playButton").textContent="Play";if(state.animation.requestId)cancelAnimationFrame(state.animation.requestId);state.animation.requestId=null;state.animation.last=null;}
function drawAnimation(){const c=$("animationCanvas"),ctx=c.getContext("2d"),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle="#fff";ctx.fillRect(0,0,w,h);const r=getSelectedResult();if(!r){centerText(ctx,w,h,"Run LP or MILP first.");return;}const pos=levelPositions(r.Nodes,w,h);for(const a of filteredArcs(r,false))drawEdge(ctx,pos,a,modeColors[a.Mode],2,false,null);for(const n of r.Nodes)drawNode(ctx,n,pos.get(n.Node));for(const pt of state.animation.particles){if(!pt.p||!pt.q)continue;const u=(state.animation.t*pt.speed+pt.offset)%1,x=pt.p.x+(pt.q.x-pt.p.x)*u,y=pt.p.y+(pt.q.y-pt.p.y)*u;ctx.fillStyle=pt.color;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();}$("animInfo").textContent=`${r.label} | ${r.UsedArcTable.length} used arcs | animation time ${state.animation.t.toFixed(1)}`;}

$("runSensitivityButton").addEventListener("click",runSensitivity);
let sensitivityRunning=false;

function cloneSensitivityData(data){
  return {
    Supply:data.Supply.map(r=>({...r})),
    Demand:data.Demand.map(r=>({...r})),
    Params:data.Params.map(r=>({...r})),
    ParamMap:{...data.ParamMap},
    Arcs:data.Arcs.map(r=>({...r})),
    ArcsAll:data.ArcsAll.map(r=>({...r})),
    Nodes:data.Nodes.map(r=>({...r})),
    NodeConstraints:data.NodeConstraints.map(r=>({...r})),
    AllowedConnections:data.AllowedConnections.map(r=>({...r}))
  };
}

function renderSensitivityResults(){
  fill(
    $("sensitivityTable").querySelector("tbody"),
    state.sensitivity,
    r=>[
      r.Scenario,
      r.Scale,
      r.Status,
      fmt(r.TotalCost),
      fmt(r.OpenNodes),
      fmt(r.TotalCO2)
    ]
  );

  const ok=state.sensitivity.filter(r=>r.Status==="OK");

  if(ok.length){
    chart(
      "sensitivityChart",
      "line",
      ok.map(r=>r.Scale),
      [
        {label:"TotalCost",data:ok.map(r=>r.TotalCost),yAxisID:"y"},
        {label:"TotalCO2",data:ok.map(r=>r.TotalCO2),yAxisID:"y1"}
      ],
      "Value"
    );

    const ch=charts["sensitivityChart"];
    ch.options.scales.y1={
      beginAtZero:true,
      position:"right",
      grid:{drawOnChartArea:false},
      title:{display:true,text:"Total CO₂"}
    };
    ch.options.scales.y.title={display:true,text:"Total Cost"};
    ch.update("none");
  }else if(charts["sensitivityChart"]){
    charts["sensitivityChart"].destroy();
    delete charts["sensitivityChart"];
  }
}

function applySensitivityScale(clone,scenario,scale){
  if(scenario==="demand"){
    clone.Demand.forEach(r=>{r.Demand*=scale;});
  }else if(scenario==="fixedcost"){
    clone.Nodes.forEach(r=>{r.FixedOpenCost*=scale;});
  }else if(scenario==="capacity"){
    clone.Nodes.forEach(r=>{
      if(Number.isFinite(r.CapWhenOpen))r.CapWhenOpen*=scale;
    });
  }else if(scenario==="modecap"){
    for(const key of ["K_road","K_rail","K_water","K_sea"]){
      const normalized=validName(key);
      if(Number.isFinite(clone.ParamMap[normalized])){
        clone.ParamMap[normalized]*=scale;
      }
    }
  }else{
    throw new Error(`Unknown sensitivity scenario: ${scenario}.`);
  }
}

function quickSensitivityFeasibilityCheck(clone,scenario){
  if(scenario!=="demand")return;

  const totalSupply=sum(clone.Supply.map(r=>r.Supply));
  const domesticDemand=sum(clone.Demand.map(r=>r.Demand));
  const minimumExport=getParam(clone.ParamMap,"exportDemand",0);

  if(domesticDemand+minimumExport>totalSupply+1e-8){
    throw new Error(
      `Pre-check infeasible: domestic demand ${fmt(domesticDemand)} + minimum export ${fmt(minimumExport)} exceeds supply ${fmt(totalSupply)}.`
    );
  }
}

async function runSensitivity(){
  if(sensitivityRunning)return;

  const button=$("runSensitivityButton");
  const originalText=button.textContent;

  try{
    if(!state.data)throw new Error("Import or load a workbook first.");
    if(!state.solverReady)throw new Error("GLPK is still loading or unavailable.");

    const scenario=$("sensScenario").value;
    const scales=$("sensScales")
      .value
      .split(/[;,\s]+/)
      .filter(Boolean)
      .map(Number);

    if(!scales.length||scales.some(x=>!Number.isFinite(x)||x<=0)){
      throw new Error("Scales must be positive numbers, for example 0.8, 1.0, 1.2.");
    }

    sensitivityRunning=true;
    button.disabled=true;
    state.sensitivity=[];
    renderSensitivityResults();

    for(let index=0;index<scales.length;index++){
      const scale=scales[index];
      button.textContent=`Running ${index+1}/${scales.length}...`;
      setStatus(`MILP sensitivity ${index+1}/${scales.length}: ${scenario}, scale=${scale}. Please wait...`);

      // Let the browser paint the progress message before GLPK starts.
      await sleep(80);

      const clone=cloneSensitivityData(state.data);

      try{
        applySensitivityScale(clone,scenario,scale);
        quickSensitivityFeasibilityCheck(clone,scenario);
        validateData(clone,$("enforceEchelon").checked);

        const res=await backendSolveModel(
          clone,
          true,
          {tmlim:60,mipgap:0.001}
        );

        state.sensitivity.push({
          Scenario:scenario,
          Scale:scale,
          Status:"OK",
          TotalCost:res.totalCost,
          OpenNodes:res.KPI.OpenNodes,
          TotalCO2:res.KPI.TotalCO2
        });
      }catch(error){
        state.sensitivity.push({
          Scenario:scenario,
          Scale:scale,
          Status:error?.message||String(error),
          TotalCost:NaN,
          OpenNodes:NaN,
          TotalCO2:NaN
        });
      }

      // Show each result immediately instead of waiting for all MILPs.
      renderSensitivityResults();
      await sleep(40);
    }

    const feasible=state.sensitivity.filter(r=>r.Status==="OK").length;
    const infeasible=state.sensitivity.length-feasible;

    setStatus(
      `Sensitivity analysis completed: ${feasible} feasible, ${infeasible} infeasible/failed.`,
      feasible?"success":"warning"
    );
  }catch(error){
    setStatus(error?.message||String(error),"error");
  }finally{
    sensitivityRunning=false;
    button.textContent=originalText;
    button.disabled=!(state.data&&state.solverReady);
  }
}

$("exportExcelButton").addEventListener("click",exportResults);function exportResults(){try{if(!state.current)throw new Error("Run a model first.");const wb=XLSX.utils.book_new();const add=(name,rows)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows.length?rows:[{Message:"No data"}]),name);const r=state.current;add("Used_Arcs",r.UsedArcTable);add("All_Arcs",r.AllArcTable);add("Node_Summary",r.NodeSummary);add("Node_Open",r.NodeOpenTable);add("Flow_By_Echelon",r.FlowByEchelon);add("Mode_Summary",r.ModeSummary);add("KPI",Object.entries(r.KPI).map(([Metric,Value])=>({Metric,Value})));if(state.lp)add("LP_KPI",Object.entries(state.lp.KPI).map(([Metric,Value])=>({Metric,Value})));if(state.milp)add("MILP_KPI",Object.entries(state.milp.KPI).map(([Metric,Value])=>({Metric,Value})));if(state.sensitivity.length)add("Sensitivity",state.sensitivity);XLSX.writeFile(wb,`multi_layer_logistics_results_${timestamp()}.xlsx`,{compression:true});setStatus("Results workbook exported.","success");}catch(error){setStatus(error.message,"error");}}
$("exportPngButton").addEventListener("click",async()=>{try{if(!state.current)throw new Error("Run a model first.");const zip=new JSZip();for(const id of ["networkCanvas","gisCanvas","animationCanvas"]){zip.file(`${id}.png`,$(id).toDataURL("image/png").split(",")[1],{base64:true});}for(const [name,ch] of Object.entries(charts))if(ch?.canvas)zip.file(`${name}.png`,ch.canvas.toDataURL("image/png").split(",")[1],{base64:true});downloadBlob(await zip.generateAsync({type:"blob"}),`multi_layer_logistics_figures_${timestamp()}.zip`);setStatus("PNG figures exported in a ZIP file.","success");}catch(error){setStatus(error.message,"error");}});

for(const b of document.querySelectorAll(".tab-button"))b.addEventListener("click",()=>openTab(b.dataset.tab));function openTab(id){document.querySelectorAll(".tab-button").forEach(b=>b.classList.toggle("active",b.dataset.tab===id));document.querySelectorAll(".tab-content").forEach(x=>x.classList.toggle("active",x.id===id));}
function clearOutputs(){for(const id of ["kpiCost","kpiUsed","kpiOpenArcs","kpiOpenNodes","kpiExport","kpiCO2"])$(id).textContent="—";for(const id of ["usedTable","allArcTable","nodeSummaryTable","nodeOpenTable"])$(id).querySelector("tbody").innerHTML="";for(const key of Object.keys(charts)){charts[key].destroy();delete charts[key];}stopAnimation();}
function getParam(map,name,def){const key=validName(name);return Object.prototype.hasOwnProperty.call(map,key)&&Number.isFinite(map[key])?map[key]:def;}
function nodeHandling(p,node){const v=validName(node),c=[`h_${v}`,`h${v}`,`h${v.toUpperCase()}`];for(const k of c)if(Object.prototype.hasOwnProperty.call(p,k))return p[k];if(v.toUpperCase()==="LC")return getParam(p,"hL",0);if(v.toUpperCase()==="ICD")return getParam(p,"hICD",0);if(v.toUpperCase()==="PORT")return getParam(p,"hPORT",0);return 0;}
function nodeCapacity(p,node){const v=validName(node),c=[`K_${v}`,`K${v}`,`K${v.toUpperCase()}`];for(const k of c)if(Object.prototype.hasOwnProperty.call(p,k))return p[k];if(v.toUpperCase()==="LC")return getParam(p,"KL",Infinity);if(v.toUpperCase()==="ICD")return getParam(p,"KICD",Infinity);if(v.toUpperCase()==="PORT")return getParam(p,"KPORT",Infinity);return Infinity;}
function localNodeM(T,node,bigM){const caps=T.filter(a=>a.From===node||a.To===node).map(a=>a.Cap).filter(Number.isFinite);return caps.length?Math.min(bigM,sum(caps)):bigM;}
function validName(s){let x=String(s??"").trim().replace(/[^A-Za-z0-9_]/g,"_");if(!/^[A-Za-z]/.test(x))x="x"+x;return x;}
function str(v){return String(v??"").trim();}function isBlank(v){return v===null||v===undefined||String(v).trim()==="";}function num(v){const x=Number(String(v).replace(/,/g,"").trim());if(!Number.isFinite(x))throw new Error(`Expected numeric value, received ${v}.`);return x;}function optNum(v){if(isBlank(v))return NaN;const s=String(v).replace(/,/g,"").trim();if(/^(inf|infinity)$/i.test(s))return Infinity;const x=Number(s);return Number.isFinite(x)?x:NaN;}
function unique(a){return [...new Set(a)];}function sum(a){return a.reduce((x,y)=>x+y,0);}function fmt(v){if(Number.isNaN(v))return "—";if(v===Infinity)return "Inf";if(!Number.isFinite(v))return String(v);const a=Math.abs(v);return a!==0&&(a>=1e6||a<1e-4)?v.toExponential(4):Number(v.toFixed(3)).toString();}function escapeHtml(v){return String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;");}
function centerText(ctx,w,h,text){ctx.fillStyle="#667085";ctx.font="18px Arial";ctx.textAlign="center";ctx.fillText(text,w/2,h/2);}function sleep(ms){return new Promise(r=>setTimeout(r,ms));}function deepClone(x){return JSON.parse(JSON.stringify(x));}function deepCloneSpecial(x){return typeof structuredClone==="function"?structuredClone(x):JSON.parse(JSON.stringify(x));}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}function timestamp(){const d=new Date();return `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,"0")}${String(d.getDate()).padStart(2,"0")}_${String(d.getHours()).padStart(2,"0")}${String(d.getMinutes()).padStart(2,"0")}${String(d.getSeconds()).padStart(2,"0")}`;}

drawNetwork(null);drawGIS(null);drawAnimation();
